void handle_syscall_exit(void *ignore, struct pt_regs *regs, long ret)
{
    int syscall_nr = regs->ax;
    struct syscall_metadata *metadata = get_syscall_metadata(syscall_nr);

    if (!metadata || !metadata->enabled)
        return;

    if (!metadata->exit_event)
        return;

    struct trace_buffer *buffer = get_tracing_buffer();
    if (!buffer)
        return;

    trace_buffer_init(buffer);
    trace_record_syscall_exit(buffer, syscall_nr, ret);
    trace_submit_buffer(buffer);
}

#include <linux/tracepoint.h>

void syscall_exit_tracer(void *ignore, struct pt_regs *regs, long ret)
{
    int syscall_number = regs->ax;
    struct syscall_metadata *metadata = get_syscall_metadata(syscall_number);

    if (!metadata || !metadata->enabled)
        return;

    struct trace_event *event = metadata->exit_event;

    if (!event)
        return;

    struct trace_buffer *buffer = prepare_trace_buffer();

    if (!buffer)
        return;

    trace_buffer_write(buffer, sizeof(int), &syscall_number);
    trace_buffer_write(buffer, sizeof(long), &ret);

    submit_trace_buffer(buffer, event);
}

