void handle_syscall_exit(void *ignore, struct pt_regs *regs, long ret)
{
    int syscall_nr = regs->syscallno;
    struct syscall_metadata *metadata;

    if (syscall_nr < 0 || syscall_nr >= NR_syscalls)
        return;

    metadata = &syscall_metadata_table[syscall_nr];
    if (!metadata || !metadata->enabled)
        return;

    if (metadata->exit_event == NULL)
        return;

    struct trace_buffer *buffer = prepare_trace_buffer();
    if (!buffer)
        return;

    buffer->syscall_number = syscall_nr;
    buffer->return_value = ret;
    submit_trace_buffer(buffer);
}
